mapper.select:
select t.visit_day,t.visit_day visitDay,t.visit_way,t.visit_way visitWay,t.name,t.audit_way,t.audit_way
auditWay,t.type_id,t.type_id typeId,t.remark,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id
communityId,t.create_time createTime,td1.name visitWayName,td2.name auditWayName
from visit_type t
left join t_dict td1 on t.visit_way = td1.status_cd and td1.table_name = 'visit_type' and td1.table_columns = 'visit_way'
left join t_dict td2 on t.audit_way = td2.status_cd and td2.table_name = 'visit_type' and td2.table_columns = 'audit_way'
where 1 =1

    and t.visit_day= #{visitDay}


    and t.visit_way= #{visitWay}


    and t.name= #{name}


    and t.name like concat('%', #{nameLike}, '%')


    and t.audit_way= #{auditWay}


    and t.type_id= #{typeId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
