    ,t.b_id = #{newBId}


    , t.visit_day= #{visitDay}


    , t.visit_way= #{visitWay}


    , t.name= #{name}


    , t.audit_way= #{auditWay}


    , t.remark= #{remark}


    , t.community_id= #{communityId}

where 1=1

    and t.type_id= #{typeId}

